<div class="table-responsive"><table class="table align-middle"><thead><tr><th style="min-width:260px">Produit</th><th>Stock actuel</th><th style="width:145px">Quantité</th><th style="width:190px">Prix unitaire ({{ $currency ?? 'FCFA' }})</th><th></th></tr></thead><tbody><template x-for="(item,index) in items" :key="item.key"><tr><td><select class="form-select" :name="`items[${index}][product_id]`" x-model="item.product_id" @change="if(selected(item))item.unit_cost=selected(item).cost" required><option value="">Sélectionner…</option><template x-for="product in products" :key="product.id"><option :value="product.id" x-text="product.name + ' · ' + product.sku"></option></template></select></td><td><span x-text="selected(item)?.stock ?? '—'"></span> <span class="small muted" x-text="selected(item)?.unit ?? ''"></span></td><td><input class="form-control" type="number" min="1" step="1" :name="`items[${index}][quantity]`" x-model="item.quantity" required></td><td><input class="form-control" type="number" min="0" step="0.01" :name="`items[${index}][unit_cost]`" x-model="item.unit_cost" required></td><td><button type="button" class="btn btn-sm btn-light text-danger" @click="remove(index)" :disabled="items.length===1" aria-label="Retirer la ligne"><i class="bi bi-trash"></i></button></td></tr></template></tbody></table></div>
