@push('scripts')<script>function purchaseBuilder(products, rows){return {products,items:rows.map((r,i)=>({...r,key:i})),nextKey:rows.length,selected(item){return this.products.find(p=>String(p.id)===String(item.product_id))},add(){this.items.push({key:this.nextKey++,product_id:'',quantity:'1',unit_cost:''})},remove(index){if(this.items.length>1)this.items.splice(index,1)}}}</script>@endpush
